async function collectImagePicker(pickerId,stage,note=''){let state=imagePickerStates.get(pickerId);if(!state)return{attachments:[],added:0,removed:0};let kept=state.existing.filter(x=>!state.removedIds.has(x.id)),added=await Promise.all(state.newFiles.map(file=>imageAttachment(file,stage,note)));state.urls.forEach(url=>URL.revokeObjectURL(url));imagePickerStates.delete(pickerId);return{attachments:[...kept,...added],added:added.length,removed:state.removedIds.size}}
async function submitJob(e){e.preventDefault();if(!actor())return toast('กรุณาเพิ่มหรือเลือกผู้ทำรายการก่อน');let fd=new FormData(e.target),boxes=[...document.querySelectorAll('.item-box')],submit=e.target.querySelector('button[type=submit]');if(submit){submit.disabled=true;submit.textContent='กำลังบันทึก...'}try{let customer={name:fd.get('customerName'),phone:fd.get('phone'),contact:fd.get('contact')};let items=await Promise.all(boxes.map(async b=>{let p=db.products.find(x=>x.id===b.querySelector('[name=product]').value),picked=await collectImagePicker(b.dataset.pickerId,'intake','หลักฐานตอนรับสินค้า');return{id:id('i'),product:p,serialNo:b.querySelector('[name=serialNo]').value.trim().toUpperCase(),symptom:b.querySelector('[name=symptom]').value,accessories:b.querySelector('[name=accessories]').value,warranty:b.querySelector('[name=warranty]').value,status:'received',rounds:[],quotes:[],attachments:picked.attachments}}));let dup=items.find(i=>db.jobs.some(j=>j.items.some(x=>x.serialNo===i.serialNo&&!['closed','cancelled'].includes(x.status))));if(dup&&!confirm(`S/N ${dup.serialNo} มีงานที่ยังไม่ปิดอยู่ ต้องการสร้างต่อหรือไม่?`))return;let d=new Date(),jobNo=`JOB-${d.getFullYear()}${String(d.getMonth()+1).padStart(2,'0')}${String(d.getDate()).padStart(2,'0')}-${String(db.jobs.length+1).padStart(3,'0')}`;let j={id:id('j'),jobNo,customer,receiveMethod:fd.get('receiveMethod'),note:fd.get('note'),items,logs:[],createdAt:now(),updatedAt:now(),deleted:false};db.jobs.unshift(j);log(j,null,'สร้างใบรับสินค้า',`${items.length} รายการ · แนบรูป ${items.reduce((n,i)=>n+i.attachments.length,0)} รูป`);view='detail';selectedJob=j.id;toast('สร้างงานเรียบร้อย');render()}catch(err){toast(err.message||'ไม่สามารถบันทึกรูปภาพได้')}finally{if(submit){submit.disabled=false;submit.textContent='สร้างใบรับสินค้า'}}}
