function processAfterLog(l,current){if(l.processKey)return l.processKey;let a=l.action||'';if(/Admin รับสินค้า/.test(a))return'intake';if(/ส่งซ่อม/.test(a))return'repair';if(/รับกลับ|ซ่อมเสร็จ/.test(a))return'qc';if(/QC ไม่ผ่าน/.test(a))return'repair';if(/QC ผ่าน|พร้อมส่งคืน|ไม่พบอาการ|ซ่อมไม่ได้|ไม่อนุมัติซ่อม|เปลี่ยนสินค้า/.test(a))return'ready';if(/เริ่มส่งคืน|ส่งถึง|ลูกค้ารับสินค้า|ปิดรายการ/.test(a))return'returned';return current}
function addCalendarMonths(date,count){let d=new Date(date),day=d.getDate();d.setDate(1);d.setMonth(d.getMonth()+count);d.setDate(Math.min(day,new Date(d.getFullYear(),d.getMonth()+1,0).getDate()));return d}
function durationText(ms,startAt=null,endAt=null){ms=Math.max(0,ms);let end=endAt==null?Date.now():Number(endAt),start=startAt==null?end-ms:Number(startAt);if(!Number.isFinite(start)||!Number.isFinite(end)||end<start){end=Date.now();start=end-ms}let from=new Date(start),to=new Date(end),months=Math.max(0,(to.getFullYear()-from.getFullYear())*12+to.getMonth()-from.getMonth()),cursor=addCalendarMonths(from,months);while(months>0&&cursor>to){months--;cursor=addCalendarMonths(from,months)}let remainder=Math.max(0,to-cursor),totalMinutes=Math.floor(remainder/60000),days=Math.floor(totalMinutes/1440),hours=Math.floor(totalMinutes%1440/60),minutes=totalMinutes%60,parts=[];if(months)parts.push(`${months} เดือน`);if(days||months)parts.push(`${days} วัน`);if(hours||days||months)parts.push(`${hours} ชม.`);if(minutes||hours||days||months)parts.push(`${minutes} นาที`);return parts.join(' ')||`${Math.max(1,Math.floor(remainder/1000))} วินาที`}
function timelineMetrics(j){let totals=Object.fromEntries(processGroups.map(p=>[p.key,0])),anchors={},nowMs=Date.now(),deliveredPattern=/ยืนยันส่งถึง|ลูกค้ารับสินค้า/,addTime=(key,from,to)=>{let elapsed=Math.max(0,to-from);totals[key]=(totals[key]||0)+elapsed;if(anchors[key]==null)anchors[key]=from};j.items.forEach(item=>{let start=Date.parse(j.createdAt)||nowMs,logs=j.logs.filter(l=>!l.itemId||l.itemId===item.id).slice().sort((a,b)=>Date.parse(a.at)-Date.parse(b.at)),current='approve',cursor=start,endLog=logs.find(l=>deliveredPattern.test(l.action||'')),end=endLog?Date.parse(endLog.at):nowMs;logs.forEach(l=>{let at=Math.min(end,Math.max(cursor,Date.parse(l.at)||cursor));addTime(current,cursor,at);current=processAfterLog(l,current);cursor=at});if(cursor<end)addTime(current,cursor,end)});let start=Date.parse(j.createdAt)||nowMs,deliveryLogs=j.logs.filter(l=>deliveredPattern.test(l.action||'')),allDelivered=j.items.every(i=>['delivered','closed','cancelled'].includes(i.status)),end=allDelivered&&deliveryLogs.length?Math.max(...deliveryLogs.map(l=>Date.parse(l.at)||start)):nowMs,total=end-start,activeKeys=[...new Set(j.items.filter(i=>!['delivered','closed','cancelled'].includes(i.status)).map(i=>processKeyForStatus(i.status)).filter(Boolean))],used=processGroups.filter(p=>totals[p.key]>0),max=Math.max(1,...used.map(p=>totals[p.key]));return `<section class="timeline-summary"><div class="timeline-total"><div><small>เวลารวมตั้งแต่รับงาน${allDelivered?'จนส่งถึงลูกค้า':'ถึงปัจจุบัน'}</small><strong>${durationText(total,start,end)}</strong></div><span>${allDelivered?'ส่งถึงลูกค้าแล้ว':'กำลังดำเนินการ'}</span></div><div class="process-time-grid">${used.map(p=>`<div class="process-time ${activeKeys.includes(p.key)?'active':''}"><div><span class="process-time-step">${p.step}</span><b>${esc(p.title)}</b>${activeKeys.includes(p.key)?'<em>กำลังใช้งานอยู่</em>':''}</div><strong>${durationText(totals[p.key],anchors[p.key],anchors[p.key]+totals[p.key])}</strong><i><u style="width:${Math.max(3,Math.round(totals[p.key]/max*100))}%"></u></i></div>`).join('')}</div><p class="timeline-hint">เวลาของแต่ละ Process คำนวณตามวันและเวลาจริงในปฏิทินของทุกรายการ เพื่อช่วยดูว่างานใช้เวลาอยู่ในขั้นตอนไหน</p></section>`}
function timeline(j){return `${timelineMetrics(j)}<div class="card card-body timeline">${j.logs.map(l=>`<div class="event"><b>${esc(l.action)}</b><p>${esc(l.note||'')} ${l.note?'· ':''}${esc(l.actor)}<br>${fmt(l.at)}</p></div>`).join('')}</div>`}
function masters(){titles('ข้อมูลหลัก','ลูกค้า สินค้า Vendor และผู้ปฏิบัติงาน');$('#app').innerHTML=`<div class="grid layout"><div>${masterCard('ลูกค้า','customer',db.customers,x=>`${x.code} · ${x.name}`,x=>x.phone)}${masterCard('สินค้า','product',db.products,x=>`${x.code} · ${x.name}`,x=>`${x.brand} ${x.model}`)}</div><div>${masterCard('บริษัทซ่อม','vendor',db.vendors,x=>x.name,x=>`SLA ${x.sla} วัน`)}${masterCard('ผู้ปฏิบัติงาน','employee',db.employees,x=>x.name,x=>x.team)}</div></div>`}
function masterCard(title,type,list,main,sub){return `<div class="card" style="margin-bottom:16px"><div class="card-head"><h2>${title}</h2><button class="ghost" data-master="${type}">＋ เพิ่ม</button></div><div class="card-body mini-list">${list.map(x=>`<div class="mini"><div><b>${esc(main(x))}</b><br><small class="muted">${esc(sub(x))}</small></div></div>`).join('')}</div></div>`}
function addMaster(type){let fields={customer:['ลูกค้า','รหัส','ชื่อ','เบอร์โทร'],product:['สินค้า','รหัส','ชื่อ','รุ่น'],vendor:['Vendor','รหัส','ชื่อ','SLA (วัน)'],employee:['ผู้ปฏิบัติงาน','รหัส','ชื่อ','ทีม']}[type];modal(`เพิ่ม${fields[0]}`,`<div class="form-grid"><div class="field"><label>${fields[1]}</label><input id="mCode"></div><div class="field"><label>${fields[2]}</label><input id="mName"></div><div class="field"><label>${fields[3]}</label><input id="mExtra"></div></div>`,()=>{if(!$('#mName').value)return false;let x={id:id(type[0]),code:$('#mCode').value,name:$('#mName').value};if(type==='customer')x.phone=$('#mExtra').value;if(type==='product')x.model=$('#mExtra').value;if(type==='vendor')x.sla=Number($('#mExtra').value||7);if(type==='employee')x.team=$('#mExtra').value;db[type+'s'].push(x);save();toast('เพิ่มข้อมูลเรียบร้อย')})}
function jobItemReport(j){let avg=Math.round(j.items.reduce((sum,i)=>sum+(progress[i.status]||0),0)/Math.max(1,j.items.length)),done=j.items.filter(i=>['delivered','closed'].includes(i.status)).length;return `<section class="job-report-group"><div class="job-report-head"><div><b>${esc(j.jobNo)}</b><span>${esc(j.customer.name)} · ${j.items.length} รายการ</span></div><div><strong>${avg}%</strong><small>ส่งคืนแล้ว ${done}/${j.items.length}</small></div></div><div class="job-item-report-list">${j.items.map((i,index)=>{let stage=processGroups.find(p=>p.statuses.includes(i.status)),round=i.rounds?.at(-1),destination=round?.vendor||round?.technician||'-';return `<div class="job-item-report"><span class="job-item-no">${index+1}</span><div><b>${esc(i.product?.name||'สินค้า')} · ${esc(i.product?.model||'')}</b><small>S/N ${esc(i.serialNo)}</small></div><div><b>${stage?.step||'--'} · ${esc(stage?.title||labels[i.status])}</b><small>${esc(pendingProcessLabels[i.status]||labels[i.status])}</small></div><div><b>${esc(destination)}</b><small>ปลายทางซ่อมล่าสุด</small></div></div>`}).join('')}</div></section>`}
function reports(){titles('รายงานประสิทธิภาพ','สรุปภาพรวมระดับ Job รายการสินค้า และ Vendor');let allItems=db.jobs.flatMap(j=>j.items),rounds=allItems.flatMap(i=>i.rounds||[]),vs=db.vendors.map(v=>({name:v.name,n:rounds.filter(r=>r.vendor===v.name).length})),states=Object.entries(labels).map(([k,v])=>({name:v,n:allItems.filter(i=>i.status===k).length})).filter(x=>x.n);$('#app').innerHTML=`<div class="grid layout"><div class="card"><div class="card-head"><h2>ปริมาณรายการสินค้าตามสถานะ</h2></div><div class="card-body">${states.map(x=>`<div class="chart-row"><span>${x.name}</span><div class="bar"><i style="width:${x.n/Math.max(1,...states.map(s=>s.n))*100}%"></i></div><b>${x.n}</b></div>`).join('')||'<div class="empty">ยังไม่มีข้อมูล</div>'}</div></div><div class="card"><div class="card-head"><h2>รายการที่ส่ง Vendor</h2></div><div class="card-body">${vs.map(x=>`<div class="chart-row" style="grid-template-columns:1fr 60px"><span>${x.name}</span><b>${x.n} รายการ</b></div>`).join('')||'<div class="empty">ยังไม่มีข้อมูล</div>'}</div></div></div><div class="card job-report-card"><div class="card-head"><div><h2>สถานะแต่ละรายการภายใน Job</h2><p>หนึ่ง Job สามารถมีสินค้าหลายรายการและอยู่คนละ Process หรือ Vendor ได้</p></div><strong>${db.jobs.length} Job · ${allItems.length} รายการ</strong></div><div class="card-body job-report-body">${db.jobs.map(jobItemReport).join('')||'<div class="empty">ยังไม่มีข้อมูล</div>'}</div></div>`}
