function upsertByCode(target,rows){let added=0;rows.forEach(row=>{if(!target.some(x=>x.code===row.code||x.name===row.name)){target.push(structuredClone(row));added++}});return added}
function ago(days,hours=0){return new Date(Date.now()-((days*24+hours)*3600000)).toISOString()}
function demoActor(name){return demoMaster.employees.find(e=>e.name===name)}
function demoLog(action,actorName,days,note='',itemId=null){let a=demoActor(actorName);return{id:id('l'),itemId,action,note,actor:`${a.name} · ${a.team}`,at:ago(days)}}
function demoItem(batch,index,status,vendor=null){
  let product=structuredClone(demoMaster.products[index%demoMaster.products.length]),itemId=`${batch}-item-${index+1}`,serialNo=`${product.code}-${batch.slice(-5).toUpperCase()}-${String(index+1).padStart(2,'0')}`;
  let item={id:itemId,product,serialNo,symptom:['เปิดเครื่องไม่ติด','ค่าที่วัดคลาดเคลื่อน','แบตเตอรี่ไม่เก็บไฟ','มีเสียงผิดปกติ','หน้าจอแสดงผลไม่ครบ'][index%5],accessories:index%2?'Adapter และสายไฟ':'ตัวเครื่องพร้อมกระเป๋า',warranty:index%3?'in':'out',status,rounds:[],quotes:[]};
  if(['quote_pending','approved_for_repair','return_unrepaired'].includes(status))item.quotes.push({id:id('q'),revision:1,amount:1800+(index*175),note:'ค่าแรงและอะไหล่ตามผลตรวจ',status:status==='quote_pending'?'รออนุมัติ':status==='return_unrepaired'?'ไม่อนุมัติ':'อนุมัติ',createdAt:ago(8-index%4)});
  let repairStates=['waiting_repair_handoff','repair_in_progress','waiting_parts','repair_completed','qc_failed','ready_to_return','return_in_progress','delivered','closed'];
  if(repairStates.includes(status)){
    let destination=vendor||'นายเบสพั๊งค์';
    item.rounds.push({round:1,vendor:destination,tracking:destination==='นายเบสพั๊งค์'?'ส่งมอบภายใน':`TH-DMO-${batch.slice(-4)}${index+1}`,sentAt:ago(7-index%3),acceptedAt:status==='waiting_repair_handoff'?null:ago(6-index%3),result:status==='qc_failed'?'QC ไม่ผ่าน':status==='waiting_parts'?'รออะไหล่':status==='repair_in_progress'?'กำลังซ่อม':'ซ่อมเสร็จ'});
    if(status==='qc_failed'){item.rounds[0].qcNote='ค่าทดสอบยังคลาดเคลื่อนเกินเกณฑ์';item.rounds.push({round:2,vendor:'นายเบสพั๊งค์',tracking:'ส่งกลับแก้ไขภายใน',sentAt:ago(1),acceptedAt:ago(1),result:'กำลังแก้ไข'})}
  }
  if(status==='replaced')item.replacement={oldSerial:serialNo,newSerial:`NEW-${serialNo}`,note:'เปลี่ยนเครื่องตามเงื่อนไขรับประกัน',at:ago(1)};
  return item
}
function demoTimeline(item,index){
  let logs=[demoLog('สร้างใบรับสินค้า',['นายเอ็ม','นายเมฆ','นายเท่ห์','นายบอล'][index%4],12-index%5,'รับสินค้าจากโรงพยาบาล',item.id)];
  if(item.status!=='received')logs.push(demoLog('Admin รับสินค้า',['น้องมิ้น','พี่ชมพู่','น้องเดียร์'][index%3],11-index%5,'ตรวจนับอุปกรณ์ครบ',item.id));
  if(!['received','admin_received'].includes(item.status))logs.push(demoLog('เริ่มตรวจสอบอาการ','นายเบสพั๊งค์',10-index%5,item.symptom,item.id));
  if(item.quotes.length)logs.push(demoLog('ออกใบเสนอราคา','พี่ชมพู่',8-index%4,`฿${Number(item.quotes[0].amount).toLocaleString()}`,item.id));
  if(item.rounds.length)logs.push(demoLog('ส่งซ่อมรอบที่ 1','น้องเดียร์',7-index%3,item.rounds[0].vendor,item.id));
  if(['repair_completed','qc_failed','ready_to_return','return_in_progress','delivered','closed'].includes(item.status))logs.push(demoLog('รับกลับและทดสอบ QC','นายเบสพั๊งค์',3,item.status==='qc_failed'?'QC ไม่ผ่าน':'ผลทดสอบผ่านเกณฑ์',item.id));
  if(['ready_to_return','return_in_progress','delivered','closed'].includes(item.status))logs.push(demoLog('พร้อมส่งคืน','น้องมิ้น',2,'ตรวจอุปกรณ์และเอกสารครบ',item.id));
  if(['delivered','closed'].includes(item.status))logs.push(demoLog('ยืนยันลูกค้ารับสินค้า','นายบอล',1,'ผู้แทนโรงพยาบาลรับเรียบร้อย',item.id));
  if(item.status==='closed')logs.push(demoLog('ปิดรายการสินค้า','พี่ชมพู่',0,'ดำเนินการครบถ้วน',item.id));
  if(item.status==='no_fault_found')logs.push(demoLog('ตรวจไม่พบอาการ','นายเบสพั๊งค์',2,'ทดสอบต่อเนื่อง 24 ชั่วโมงไม่พบความผิดปกติ',item.id));
  if(item.status==='cannot_repair')logs.push(demoLog('ระบุว่าซ่อมไม่ได้','นายเบสพั๊งค์',2,'อะไหล่ยกเลิกการผลิต',item.id));
  if(item.status==='return_unrepaired')logs.push(demoLog('ลูกค้าไม่อนุมัติซ่อม','น้องมิ้น',2,'ขอรับเครื่องคืนโดยไม่ซ่อม',item.id));
  if(item.status==='replaced')logs.push(demoLog('เปลี่ยนสินค้า','พี่ชมพู่',1,`${item.serialNo} → ${item.replacement.newSerial}`,item.id));
  return logs
}
function createDemoBatch(){
  let stamp=Date.now().toString(36),batch=`DEMO-${stamp}`,added={employees:upsertByCode(db.employees,demoMaster.employees),customers:upsertByCode(db.customers,demoMaster.customers),products:upsertByCode(db.products,demoMaster.products),vendors:upsertByCode(db.vendors,demoMaster.vendors)};
  let scenarios=[
    ['received'],['admin_received','diagnosing'],['quote_pending','approved_for_repair'],['waiting_repair_handoff','repair_in_progress'],
    ['waiting_parts','repair_completed'],['qc_failed','ready_to_return'],['return_in_progress','delivered'],['closed','no_fault_found'],
    ['cannot_repair','return_unrepaired'],['replacement_pending','replaced']
  ];
  let destinations=['บริษัท Omron','บริษัท Yuwel','บริษัท AND','บริษัท Monitor','นายเบสพั๊งค์'];
  let jobs=scenarios.map((statuses,jx)=>{
    let items=statuses.map((status,ix)=>demoItem(batch,jx*2+ix,status,destinations[(jx*2+ix)%destinations.length]));
    let logs=items.flatMap((item,ix)=>demoTimeline(item,jx*2+ix)).sort((a,b)=>b.at.localeCompare(a.at));
    return{id:`${batch}-job-${jx+1}`,demoBatchId:batch,jobNo:`JOB-DEMO-${stamp.toUpperCase()}-${String(jx+1).padStart(2,'0')}`,customer:structuredClone(demoMaster.customers[jx%demoMaster.customers.length]),receiveMethod:['ลูกค้านำส่ง','รับ Onsite','ขนส่ง'][jx%3],note:`ข้อมูลจำลองชุด ${batch}`,items,logs,createdAt:ago(14-jx),updatedAt:logs[0]?.at||now(),deleted:false}
  });
  db.jobs.unshift(...jobs);db.demoBatches.push({id:batch,createdAt:now(),jobCount:jobs.length,itemCount:jobs.reduce((n,j)=>n+j.items.length,0)});save();refreshActorSelect();return{batch,jobs:jobs.length,items:jobs.reduce((n,j)=>n+j.items.length,0),added}
}
function confirmCreateDemo(){modal('สร้างข้อมูลจำลอง',`<div class="confirm-summary"><p>ระบบจะ <b>เพิ่มข้อมูลต่อท้าย</b> โดยไม่ลบงานเดิม และจะไม่สร้าง Master Data ชื่อเดิมซ้ำ</p><ul><li>10 Jobs / 19 Items ครอบคลุมทุกสถานะ</li><li>โรงพยาบาล 5 แห่ง</li><li>Service 4 คน, Admin 3 คน, ช่างภายใน 1 คน</li><li>Vendor ภายนอก 4 บริษัท</li></ul></div>`,()=>{let result=createDemoBatch();view='dashboard';selectedJob=null;toast(`สร้าง ${result.jobs} Jobs / ${result.items} Items เรียบร้อย`)})}
function confirmClearAll(){modal('ล้างข้อมูลทั้งหมด',`<div class="danger-zone"><p><b>ข้อมูลทั้งหมดจะถูกลบจาก Browser เครื่องนี้</b></p><p>รวม Jobs, Timeline, ลูกค้า, สินค้า, Vendor และรายชื่อผู้ปฏิบัติงาน แนะนำให้ส่งออกข้อมูลสำรองก่อนดำเนินการ</p><div class="field"><label>พิมพ์ “ล้างข้อมูลทั้งหมด” เพื่อยืนยัน</label><input id="clearPhrase" autocomplete="off" placeholder="ล้างข้อมูลทั้งหมด"></div></div>`,()=>{if($('#clearPhrase').value!=='ล้างข้อมูลทั้งหมด'){toast('ข้อความยืนยันไม่ถูกต้อง');return false}db=emptyDatabase();save();localStorage.removeItem('sp-actor');view='dashboard';selectedJob=null;refreshActorSelect();toast('ล้างข้อมูลทั้งหมดแล้ว')})}
function exportData(){let b=new Blob([JSON.stringify(db,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=`servicepro-backup-${new Date().toISOString().slice(0,10)}.json`;a.click();URL.revokeObjectURL(a.href);toast('ส่งออกข้อมูลแล้ว')}
function importData(e){let f=e.target.files[0];if(!f)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!x.jobs||!x.customers)throw 0;if(confirm('การนำเข้าจะแทนที่ข้อมูลปัจจุบัน ต้องการดำเนินการหรือไม่?')){db=x;save();init();toast('นำเข้าข้อมูลเรียบร้อย')}}catch{alert('ไฟล์ข้อมูลไม่ถูกต้อง')}};r.readAsText(f);e.target.value=''}
const baseProcessItemCard=itemCard;
itemCard=function(j,i,contextKey=''){let html=baseProcessItemCard(j,i,contextKey);if(contextKey!=='repair')return html;let warranty=i.warranty==='in'?['ในประกัน','in']:i.warranty==='out'?['นอกประกัน','out']:['รอตรวจสอบสถานะประกัน','unknown'],decision=i.repairDecision||'',decisionPanel=`<section class="repair-decision" data-decision-panel="${i.id}"><div class="repair-decision-head"><div><small>สถานะการดำเนินการซ่อม</small><b>เลือกว่าเครื่องรายการนี้จะซ่อมหรือไม่ซ่อม</b></div>${i.repairDecisionAt?`<span>บันทึกล่าสุด ${fmt(i.repairDecisionAt)}</span>`:'<span class="pending">ยังไม่ได้บันทึก</span>'}</div><div class="repair-decision-controls"><input type="radio" id="decision-${i.id}-repair" name="decision-${i.id}" value="repair" ${decision==='repair'?'checked':''}><label class="decision-repair" for="decision-${i.id}-repair">✓ ซ่อม</label><input type="radio" id="decision-${i.id}-no" name="decision-${i.id}" value="no_repair" ${decision==='no_repair'?'checked':''}><label class="decision-no-repair" for="decision-${i.id}-no">✕ ไม่ซ่อม</label><button type="button" class="save-repair-decision" data-save-repair-decision="1" data-job-id="${j.id}" data-item-id="${i.id}">บันทึกรายการแก้ไข</button></div></section>`;return html.replace('<div class="progress">',`<div class="warranty-alert ${warranty[1]}"><span>สถานะประกัน</span><strong>${warranty[0]}</strong></div><div class="progress">`).replace('<div class="item-actions">',`${decisionPanel}<div class="item-actions">`)}
function saveRepairDecision(button){if(!actor())return toast('กรุณาเพิ่มหรือเลือกผู้ทำรายการก่อน');let j=db.jobs.find(x=>x.id===button.dataset.jobId),i=j?.items.find(x=>x.id===button.dataset.itemId),panel=button.closest('.repair-decision'),choice=panel?.querySelector('input[type=radio]:checked')?.value;if(!j||!i)return;if(!choice)return toast('กรุณาเลือก “ซ่อม” หรือ “ไม่ซ่อม” ก่อนบันทึก');let changed=i.repairDecision!==choice;i.repairDecision=choice;i.repairDecisionAt=now();i.repairDecisionBy=actor()?.name||'';log(j,i,'บันทึกสถานะการซ่อม',choice==='repair'?'เลือกดำเนินการซ่อม':'เลือกไม่ซ่อม');toast(changed?'บันทึกสถานะการซ่อมแล้ว':'ยืนยันสถานะเดิมและบันทึก Log แล้ว');render()}
document.addEventListener('click',e=>{let button=e.target.closest('[data-save-repair-decision]');if(button)saveRepairDecision(button)})
const processItemCardWithDecision=itemCard;
