saveRepairDecision=function(button){if(!actor())return toast('กรุณาเพิ่มหรือเลือกผู้ทำรายการก่อน');let j=db.jobs.find(x=>x.id===button.dataset.jobId),i=j?.items.find(x=>x.id===button.dataset.itemId),panel=button.closest('.repair-decision'),inspection=panel?.querySelector(`input[name="inspection-${i?.id}"]:checked`)?.value;if(!j||!i)return;if(!inspection)return toast('กรุณาเลือก “กำลังตรวจเชค” หรือ “รอตรวจเชค”');let decision=panel.querySelector(`input[name="decision-${i.id}"]:checked`)?.value,approval=panel.querySelector(`input[name="approval-${i.id}"]:checked`)?.value;if(inspection==='inspecting'&&!decision)return toast('กรุณาเลือก “ซ่อม” หรือ “ไม่ซ่อม”');if(inspection==='inspecting'&&i.warranty==='out'&&!approval)return toast('กรุณาเลือก “รอใบ PO” หรือ “อนุมัติซ่อม”');i.inspectionStatus=inspection;i.repairDecision=inspection==='inspecting'?decision:'';i.repairApprovalStatus=inspection==='inspecting'&&i.warranty==='out'?approval:'';i.repairDecisionAt=now();i.repairDecisionBy=actor()?.name||'';let notes=[inspection==='inspecting'?'กำลังตรวจเชค':'รอตรวจเชค'];if(inspection==='inspecting'){notes.push(decision==='repair'?'ซ่อม':'ไม่ซ่อม');if(i.warranty==='out')notes.push(approval==='waiting_po'?'รอใบ PO':'อนุมัติซ่อม')}log(j,i,'บันทึกสถานะงานซ่อม',notes.join(' · '));toast('บันทึกสถานะงานซ่อมเรียบร้อย');render()}
