function enhanceSearchableSelect(select){if(select.dataset.searchEnhanced)return;select.dataset.searchEnhanced='1';let field=select.closest('.field'),label=field?.querySelector(':scope > label')?.textContent.replace('*','').trim()||'ข้อมูล',wrap=document.createElement('div');wrap.className='search-combobox';let input=document.createElement('input'),list=document.createElement('div');input.type='text';input.dataset.searchOnly='1';input.autocomplete='off';input.placeholder=`พิมพ์เพื่อค้นหา${label}`;input.setAttribute('role','combobox');input.setAttribute('aria-expanded','false');input.setAttribute('aria-label',`ค้นหาและเลือก${label}`);list.className='search-combobox-list';list.setAttribute('role','listbox');wrap.append(input,list);select.parentElement.insertBefore(wrap,select);select.classList.add('search-combobox-native');let open=()=>{wrap.classList.add('open');input.setAttribute('aria-expanded','true')},close=()=>{wrap.classList.remove('open');input.setAttribute('aria-expanded','false')},choose=option=>{select.value=option.value;input.value=option.textContent.trim();input.dataset.selectedValue=option.value;select.dispatchEvent(new Event('change',{bubbles:true}));close()},draw=()=>{let q=input.value.trim().toLocaleLowerCase('th'),options=[...select.options].filter(o=>o.value&&(!q||o.textContent.toLocaleLowerCase('th').includes(q)));list.innerHTML=options.length?options.map(o=>`<button type="button" role="option" data-value="${esc(o.value)}" ${o.value===select.value?'aria-selected="true"':''}>${esc(o.textContent.trim())}</button>`).join(''):'<div class="search-combobox-empty">ไม่พบข้อมูลที่ค้นหา</div>';list.querySelectorAll('[data-value]').forEach(button=>button.onclick=()=>{let option=[...select.options].find(o=>o.value===button.dataset.value);if(option)choose(option)})};input.onfocus=()=>{if(input.dataset.selectedValue){input.value='';input.dataset.selectedValue=''}draw();open()};input.oninput=()=>{select.value='';input.dataset.selectedValue='';draw();open();select.dispatchEvent(new Event('change',{bubbles:true}))};input.onkeydown=e=>{let items=[...list.querySelectorAll('[data-value]')],active=document.activeElement;if(e.key==='ArrowDown'){e.preventDefault();draw();open();(items[0]||input).focus()}else if(e.key==='Enter'){let first=items[0];if(first){e.preventDefault();first.click()}}else if(e.key==='Escape'){e.preventDefault();close();let selected=select.selectedOptions[0];input.value=selected?.value?selected.textContent.trim():''}};list.addEventListener('keydown',e=>{let items=[...list.querySelectorAll('[data-value]')],index=items.indexOf(document.activeElement);if(e.key==='ArrowDown'){e.preventDefault();items[Math.min(index+1,items.length-1)]?.focus()}else if(e.key==='ArrowUp'){e.preventDefault();if(index<=0)input.focus();else items[index-1]?.focus()}else if(e.key==='Escape'){e.preventDefault();input.focus();close()}});select.addEventListener('change',()=>{let selected=select.selectedOptions[0];if(selected?.value){input.value=selected.textContent.trim();input.dataset.selectedValue=selected.value}else if(document.activeElement!==input){input.value='';input.dataset.selectedValue=''}draw()});document.addEventListener('pointerdown',e=>{if(!wrap.contains(e.target))close()});let selected=select.selectedOptions[0];if(selected?.value){input.value=selected.textContent.trim();input.dataset.selectedValue=selected.value}draw()}
