function organizationContacts(entity){
  let source=Array.isArray(entity?.contacts)?entity.contacts:[];
  let contacts=source.map(contact=>({id:contact.id||id('ct'),name:String(contact.name||contact.contact||'').trim(),department:String(contact.department||'').trim(),phone:String(contact.phone||'').trim()})).filter(contact=>contact.name||contact.department||contact.phone);
  if(!contacts.length&&(entity?.contact||entity?.phone))contacts=[{id:id('ct'),name:String(entity.contact||'').trim(),department:String(entity.department||'').trim(),phone:String(entity.phone||'').trim()}];
  return contacts;
}
function applyOrganizationContacts(entity,contacts){
  let clean=(contacts||[]).map(contact=>({id:contact.id||id('ct'),name:String(contact.name||'').trim(),department:String(contact.department||'').trim(),phone:String(contact.phone||'').trim()})).filter(contact=>contact.name||contact.department||contact.phone);
  entity.contacts=clean;entity.contact=clean[0]?.name||'';entity.phone=clean[0]?.phone||'';return entity;
}
