  root.querySelector('[data-contact-add]').onclick=()=>{root._contacts=getContactEditorContacts(editorId,true);root._contacts.push({id:id('ct'),name:'',department:'',phone:''});draw();root.querySelector('.organization-contact-row:last-child [data-contact-name]')?.focus()};draw();
