function getContactEditorContacts(editorId,includeBlank=false){let root=document.getElementById(editorId);if(!root)return[];let contacts=[...root.querySelectorAll('.organization-contact-row')].map(row=>({id:row.dataset.contactId||id('ct'),name:row.querySelector('[data-contact-name]')?.value.trim()||'',department:row.querySelector('[data-contact-department]')?.value.trim()||'',phone:row.querySelector('[data-contact-phone]')?.value.trim()||''}));return includeBlank?contacts:contacts.filter(contact=>contact.name||contact.department||contact.phone)}
